SELECT to_regclass('public.behavior76_windows') IS NOT NULL AS windows_exists,to_regclass('public.session_ownership') IS NOT NULL AS public_lease_exists,to_regclass('public.accepted_inputs') IS NOT NULL AS public_inputs_exists; SELECT c.relname,a.attname,count(DISTINCT n.nspname) AS schemas FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped WHERE c.relkind='r' AND c.relname IN('session_ownership','accepted_inputs') AND n.nspname NOT LIKE 'pg_%' GROUP BY c.relname,a.attname ORDER BY c.relname,a.attname;